63. 		this.databaseClientProvider = databaseClientProvider;
64. 	}
65. 
66. 	@Override
67. 	protected Object doGetTransaction() throws TransactionException {
68. 		Tx tx = (Tx) TransactionSynchronizationManager.getResource(databaseClientProvider.get());
69. 		if (tx != null && tx.getTransactionContext() != null
70. 				&& (tx.getTransactionManager() != null
71. 						&& tx.getTransactionManager().getState() == TransactionManager.TransactionState.STARTED ||
72. 						tx.isReadOnly())) {
73. 			return tx;
74. 		}
75. 		return new Tx(databaseClientProvider.get());
76. 	}
