80. 			throws TransactionException {
81. 		if (transactionDefinition.getIsolationLevel() != TransactionDefinition.ISOLATION_DEFAULT) {
82. 			throw new IllegalStateException(
83. 					"SpannerTransactionManager supports only isolation level TransactionDefinition.ISOLATION_DEFAULT");
84. 		}
85. 		if (transactionDefinition.getPropagationBehavior() != TransactionDefinition.PROPAGATION_REQUIRED) {
