123. 				public long[] batchUpdate(Iterable<Statement> iterable) {
124. 					throw new IllegalStateException(DML_ERROR_MSG);
125. 				}
126. 
127. 				@Override
128. 				public ApiFuture<long[]> batchUpdateAsync(Iterable<Statement> iterable) {
129. 					throw new IllegalStateException(DML_ERROR_MSG);
130. 				}
131. 
