16. 
17. package com.google.cloud.spring.autoconfigure.firestore;
18. 
19. import java.io.IOException;
20. 
21. import com.google.api.gax.core.CredentialsProvider;
22. import com.google.api.gax.grpc.InstantiatingGrpcChannelProvider;
23. import com.google.cloud.firestore.Firestore;
24. import com.google.cloud.firestore.FirestoreOptions;
25. import com.google.cloud.spring.autoconfigure.core.GcpContextAutoConfiguration;
26. import com.google.cloud.spring.core.DefaultCredentialsProvider;
27. import com.google.cloud.spring.core.GcpProjectIdProvider;
28. import com.google.cloud.spring.core.UserAgentHeaderProvider;
29. import com.google.cloud.spring.data.firestore.FirestoreTemplate;
30. import com.google.cloud.spring.data.firestore.mapping.FirestoreClassMapper;
31. import com.google.cloud.spring.data.firestore.mapping.FirestoreDefaultClassMapper;
32. import com.google.cloud.spring.data.firestore.mapping.FirestoreMappingContext;
33. import com.google.cloud.spring.data.firestore.transaction.ReactiveFirestoreTransactionManager;
34. import com.google.firestore.v1.FirestoreGrpc;
35. import io.grpc.ManagedChannel;
36. import io.grpc.ManagedChannelBuilder;
37. import io.grpc.auth.MoreCallCredentials;
38. import reactor.core.publisher.Flux;
39. 
40. import org.springframework.beans.factory.annotation.Qualifier;
41. import org.springframework.boot.autoconfigure.AutoConfigureAfter;
42. import org.springframework.boot.autoconfigure.condition.ConditionalOnClass;
43. import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
44. import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
45. import org.springframework.boot.context.properties.EnableConfigurationProperties;
46. import org.springframework.context.annotation.Bean;
47. import org.springframework.context.annotation.Configuration;
48. 
49. /**
50.  * Provides classes to use with Cloud Firestore.
51.  *
52.  * @author Dmitry Solomakha
53.  *
54.  * @since 1.2
55.  */
56. @Configuration(proxyBeanMethods = false)
57. @AutoConfigureAfter(GcpContextAutoConfiguration.class)
58. @ConditionalOnProperty(value = "spring.cloud.gcp.firestore.enabled", matchIfMissing = true)
59. @ConditionalOnClass({ Firestore.class })
60. @EnableConfigurationProperties(GcpFirestoreProperties.class)
61. public class GcpFirestoreAutoConfiguration {
62. 
63. 	private static final String ROOT_PATH_FORMAT = "projects/%s/databases/(default)/documents";
64. 
65. 	private static final UserAgentHeaderProvider USER_AGENT_HEADER_PROVIDER =
66. 			new UserAgentHeaderProvider(GcpFirestoreAutoConfiguration.class);
67. 
68. 	private final String projectId;
69. 
70. 	private final CredentialsProvider credentialsProvider;
71. 
72. 	private final String hostPort;
73. 
74. 	private final String firestoreRootPath;
75. 
76. 	GcpFirestoreAutoConfiguration(GcpFirestoreProperties gcpFirestoreProperties,
77. 			GcpProjectIdProvider projectIdProvider,
78. 			CredentialsProvider credentialsProvider) throws IOException {
79. 
80. 		this.projectId = (gcpFirestoreProperties.getProjectId() != null)
81. 				? gcpFirestoreProperties.getProjectId()
82. 				: projectIdProvider.getProjectId();
83. 
84. 		this.credentialsProvider = (gcpFirestoreProperties.getCredentials().hasKey()
85. 				? new DefaultCredentialsProvider(gcpFirestoreProperties)
86. 				: credentialsProvider);
87. 
88. 		this.hostPort = gcpFirestoreProperties.getHostPort();
89. 		this.firestoreRootPath = String.format(ROOT_PATH_FORMAT, this.projectId);
90. 	}
91. 
92. 	@Bean
93. 	@ConditionalOnMissingBean
94. 	public FirestoreOptions firestoreOptions() {
95. 		return FirestoreOptions.getDefaultInstance().toBuilder()
96. 				.setCredentialsProvider(this.credentialsProvider)
97. 				.setProjectId(this.projectId)
98. 				.setHeaderProvider(USER_AGENT_HEADER_PROVIDER)
99. 				.setChannelProvider(
100. 						InstantiatingGrpcChannelProvider.newBuilder()
101. 								.setEndpoint(this.hostPort)
102. 								.build())
103. 				.build();
104. 	}
105. 
106. 	@Bean
107. 	@ConditionalOnMissingBean
108. 	public Firestore firestore(FirestoreOptions firestoreOptions) {
109. 		return firestoreOptions.getService();
110. 	}
111. 
112. 	/**
113. 	 * The Firestore reactive template and data repositories support auto-configuration.
114. 	 */
115. 	@ConditionalOnClass({ FirestoreGrpc.FirestoreStub.class, Flux.class })
116. 	class FirestoreReactiveAutoConfiguration {
117. 		@Bean
118. 		@ConditionalOnMissingBean
119. 		public FirestoreGrpc.FirestoreStub firestoreGrpcStub(
120. 				@Qualifier("firestoreManagedChannel") ManagedChannel firestoreManagedChannel) throws IOException {
121. 			return FirestoreGrpc.newStub(firestoreManagedChannel)
122. 					.withCallCredentials(MoreCallCredentials.from(
123. 							GcpFirestoreAutoConfiguration.this.credentialsProvider.getCredentials()));
124. 		}
125. 
126. 		@Bean
127. 		@ConditionalOnMissingBean
128. 		public FirestoreMappingContext firestoreMappingContext() {
129. 			return new FirestoreMappingContext();
130. 		}
131. 
132. 		@Bean
133. 		@ConditionalOnMissingBean
134. 		public FirestoreClassMapper getClassMapper(FirestoreMappingContext mappingContext) {
135. 			return new FirestoreDefaultClassMapper(mappingContext);
136. 		}
137. 
138. 		@Bean
139. 		@ConditionalOnMissingBean
140. 		public FirestoreTemplate firestoreTemplate(FirestoreGrpc.FirestoreStub firestoreStub,
141. 				FirestoreClassMapper classMapper, FirestoreMappingContext firestoreMappingContext) {
142. 			return new FirestoreTemplate(firestoreStub, GcpFirestoreAutoConfiguration.this.firestoreRootPath,
143. 					classMapper, firestoreMappingContext);
144. 		}
145. 
146. 		@Bean
147. 		@ConditionalOnMissingBean
148. 		public ReactiveFirestoreTransactionManager firestoreTransactionManager(
149. 				FirestoreGrpc.FirestoreStub firestoreStub, FirestoreClassMapper classMapper) {
150. 			return new ReactiveFirestoreTransactionManager(firestoreStub,
151. 					GcpFirestoreAutoConfiguration.this.firestoreRootPath, classMapper);
152. 		}
153. 
154. 		@Bean
155. 		@ConditionalOnMissingBean (name = "firestoreManagedChannel")
156. 		public ManagedChannel firestoreManagedChannel() {
157. 			return ManagedChannelBuilder
158. 					.forTarget("dns:///" + GcpFirestoreAutoConfiguration.this.hostPort)
159. 					.userAgent(USER_AGENT_HEADER_PROVIDER.getUserAgent())
160. 					.build();
161. 		}
162. 	}
163. }
